let sourceAsset,sourceElement,sourceIn=0,sourceOut=0;
function closeSource(){if(sourceElement?.pause)sourceElement.pause();sourceAsset=null;sourceElement=null;$('sourcePane').replaceChildren();$('sourcePane').hidden=true;document.querySelector('.stage').hidden=false;document.querySelector('.transport').hidden=false}
function openSource(a){if(!url(a))return say('Import the original file to relink this asset.');pause();closeSource();sourceAsset=a;sourceIn=0;sourceOut=a.duration;let box=$('sourcePane');box.hidden=false;document.querySelector('.stage').hidden=true;document.querySelector('.transport').hidden=true;let el=document.createElement(a.type==='image'?'img':a.type);el.src=url(a);el.controls=true;sourceElement=el;let bar=document.createElement('div'),name=document.createElement('strong'),range=document.createElement('output');name.textContent='Source · '+a.name;bar.append(name,button('Program ×',closeSource));let tools=document.createElement('div');let update=()=>range.value=tc(sourceIn)+' – '+tc(sourceOut);function mark(which){let t=snap(el.currentTime||0);if(which==='in')sourceIn=limit(t,0,sourceOut-1/fps);else sourceOut=limit(t,sourceIn+1/fps,a.duration);update()}
if(a.type!=='image')tools.append(button('Mark In (I)',()=>mark('in')),button('Mark Out (O)',()=>mark('out')));tools.append(range,button('Append',()=>{let s=sourceIn,d=sourceOut-s;closeSource();insert(a);let c=selected();c.offset=s;c.dur=Math.max(1/fps,snap(d));edited()}));box.append(bar,el,tools);update()}
document.addEventListener('keydown',e=>{if(!sourceAsset||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;let k=e.key.toLowerCase();if(k==='escape'){closeSource();return}let label=k==='i'?'Mark In (I)':k==='o'?'Mark Out (O)':null;if(label)[...$('sourcePane').querySelectorAll('button')].find(b=>b.textContent===label)?.click()});
async function pickLut(c){let input=document.createElement('input');input.type='file';input.accept='.cube';input.onchange=async()=>{try{let rows=[],size=0;for(let raw of (await input.files[0].text()).split(/\r?\n/)){let line=raw.split('#')[0].trim();if(!line||line.startsWith('TITLE'))continue;let parts=line.split(/\s+/);if(parts[0]==='LUT_3D_SIZE'){size=Number(parts[1]);continue}if(parts[0]==='DOMAIN_MIN'&&parts.slice(1).every(v=>+v===0)||parts[0]==='DOMAIN_MAX'&&parts.slice(1).every(v=>+v===1))continue;let rgb=parts.map(Number);if(rgb.length!==3||!rgb.every(Number.isFinite))throw Error('Expected a standard-domain 3D .cube file');rows.push(...rgb)}if(size<2||size>65||!Number.isInteger(size)||rows.length!==size**3*3)throw Error('Invalid LUT grid (supported sizes 2–65)');let bytes=new Uint8Array(rows.map(v=>limit(Math.round(v*255),0,255)));let chunks=[];for(let i=0;i<bytes.length;i+=16000)chunks.push(String.fromCharCode(...bytes.subarray(i,i+16000)));remember();c.lut={size,data:btoa(chunks.join(''))};edited();say('Applied '+input.files[0].name)}catch(err){say(err.message)}};input.click()}
const lutCache=new WeakMap();
function graded(src,w,h,c){let sw=Math.min(w,exporting?canvas.width:960),sh=Math.max(1,Math.round(h*sw/w));if(keyCanvas.width!==sw||keyCanvas.height!==sh){keyCanvas.width=sw;keyCanvas.height=sh}keyCtx.drawImage(src,0,0,sw,sh);let pixels=keyCtx.getImageData(0,0,sw,sh),p=pixels.data,original=c.sharpen?new Uint8ClampedArray(p):null,table;
if(c.lut){table=lutCache.get(c.lut);if(!table){table=Uint8Array.from(atob(c.lut.data),ch=>ch.charCodeAt(0));lutCache.set(c.lut,table)}}
for(let i=0;i<p.length;i+=4){let r=p[i],g=p[i+1],b=p[i+2];if(c.key&&g>r*1.35&&g>b*1.35){p[i+3]=0;continue}if(table){let s=c.lut.size,n=s-1,j=3*(Math.round(r*n/255)+s*(Math.round(g*n/255)+s*Math.round(b*n/255)));p[i]=table[j];p[i+1]=table[j+1];p[i+2]=table[j+2]}if(c.warmth){p[i]+=c.warmth*.35;p[i+2]-=c.warmth*.35}if(original&&i>=sw*4+4&&i<p.length-sw*4-4){for(let k=i;k<i+3;k++)p[k]+=(4*original[k]-original[k-4]-original[k+4]-original[k-sw*4]-original[k+sw*4])*c.sharpen/200}}
keyCtx.putImageData(pixels,0,0);return keyCanvas}
function keyValue(c,key,t,fallback){let frames=c.keys;if(!frames?.length)return fallback;let left=frames[0],right=frames.at(-1);if(t<=left.t)return left[key];if(t>=right.t)return right[key];for(let i=1;i<frames.length;i++)if(frames[i].t>=t){left=frames[i-1];right=frames[i];break}return left[key]+(right[key]-left[key])*(t-left.t)/(right.t-left.t)}
function keyMotion(c){let t=snap(limit(time-c.start,0,c.dur));remember();c.keys=(c.keys||[]).filter(k=>Math.abs(k.t-t)>.015);c.keys.push({t,x:c.x,y:c.y,scale:c.scale,opacity:c.opacity});c.keys.sort((a,b)=>a.t-b.t);edited();say('Motion keyframe set at '+tc(t)+' within the clip.')}
async function normalize(c){try{await audio();let a=asset(c.asset),f=await retrieve(a.id);if(!f)throw Error('Original media is unavailable');say('Measuring clip audio…');let buffer=await ac.decodeAudioData(await f.arrayBuffer());let first=Math.floor(c.offset*buffer.sampleRate),last=Math.min(buffer.length,Math.ceil((c.offset+c.dur*c.speed)*buffer.sampleRate)),power=0,peak=0,count=0;for(let channel=0;channel<buffer.numberOfChannels;channel++){let data=buffer.getChannelData(channel);for(let i=first;i<last;i++){let amp=data[i];power+=amp*amp;peak=Math.max(peak,Math.abs(amp));count++}}if(!power||!count)throw Error('No audible signal in the selected range');if(!project.clips.includes(c))return;remember();c.volume=Math.round(100*Math.min(3,.891/peak,.126/Math.sqrt(power/count)));edited();say('Applied RMS normalization, limited to −1 dB sample peak.')}catch(err){say('Audio analysis unavailable: '+err.message)}}
